output_format.structure:
{
    "agent_id": "symptom_analysis_agent",
    "analysis_type": "symptom_analysis",
    "prediction": true|false,
    "confidence": 0.0-1.0,
    "reasoning": "Detailed symptom analysis reasoning",
    "key_findings": [
        "Key symptoms and findings"
    ],
    "risk_factors": [
        "Symptom-based risk factors"
    ],
    "symptom_analysis": {
        "primary_symptoms": ["string"],
        "secondary_symptoms": ["string"],
        "symptom_severity": "mild|moderate|severe",
        "symptom_duration": "string",
        "progression_pattern": "stable|improving|worsening|fluctuating"
    },
    "red_flags": [
        "Urgent symptoms requiring immediate attention"
    ],
    "differential_diagnosis": [
        "Other possible causes of symptoms"
    ],
    "clinical_concerns": [
        "Specific clinical concerns raised by symptoms"
    ],
    "recommendations": [
        "Symptom-based recommendations"
    ]
}
